export const cleanNote = (t) => cap(String(t)
  .replace(/\s*\((?:[ГРБД]\d+(?:\.\d+)?|\d+(?:\.\d+)+[а-я]?)(?:,\s*(?:шаг\s*)?[\d.а-я]+)*\)/g, '')
  .replace(/^(?:Оптимизируется|Оптимизация|Автоматизация|TO BE|AS IS)\s*:\s*/i, '')
  .replace(/\s+(?:—|-)\s*$/, '').trim());
const norm = (v) => String(v == null ? '' : v).trim().toLowerCase();
