Object.assign(S, S_DOB, S_PLAST, S_GEO, S_SEIS);

// ===== Типовая форма (по типу шага, документам и аннотациям BPMN) =====
function generic({ run, s, i, kind, obj, w }) {
  const inp = inputsOf(run, i); const sysName = s.s.find((x) => /^ABAI|^КХД/.test(x)) || s.s[0] || 'ABAI БД 2.0';
  const facts = w ? wellFacts(w) : (obj.attrs || []).slice(0, 4);
  const docs = s.d.length ? s.d.map((d) => doc(d)) : [];
  const base = { facts, docs };
  if (kind === 'approve') return { ...base, intro: `Рассмотрите материалы шага и примите решение.${s.d.length ? ' Документы подписываются ЭЦП и регистрируются в БД 2.0.' : ''}`, docs: s.d.length ? docs : inp.docs.map((d) => doc(d, 'ready')), decision: APPROVE(s.d.length > 0 || inp.docs.length > 0) };
  if (kind === 'expert') return { ...base, intro: 'Проведите экспертизу представленных материалов и зафиксируйте заключение.', docs: s.d.length ? docs : inp.docs.map((d) => doc(d, 'ready')), decision: EXPERT(s.d.length > 0) };
  if (kind === 'calc') return { ...base, intro: `Выполните расчёт в ${sysName} и примите результат.`, fields: [sel('sc', 'Сценарий', 'Базовый', ['Базовый', 'Оптимистичный', 'Консервативный']), f('hor', 'Горизонт расчёта', run.part === 'dob' ? '30 суток' : run.part === 'skv' ? 'до окончания работ' : '5 лет')], checks: [chk(`Исходные данные загружены из ${sysName}`)], action: { label: 'Принять результат расчёта', text: 'Расчёт выполнен, результат принят' } };
  if (kind === 'data') return { ...base, intro: `Внесите или подтвердите данные шага; значения сохраняются в ${sysName}.`, fields: (obj.attrs || []).slice(0, 3).map((a, k) => f('a' + k, a[0], a[1])).concat([f('date', 'Дата актуальности', dateNow())]), action: { label: 'Сохранить и передать', text: 'Данные внесены' } };
  if (kind === 'docs') return { ...base, intro: `Сформируйте документы шага в ${sysName} и передайте дальше по процессу.`, docs: docs.length ? docs : [doc(cap(s.t))], action: { label: 'Сформировать и передать', text: 'Документы сформированы' } };
  return { ...base, intro: 'Выполните работы по шагу и зафиксируйте результат.', checks: [chk('Работы по шагу выполнены', false)], action: { label: 'Завершить шаг', text: 'Шаг выполнен' } };
}

// Спецификация формы шага
export function formFor(run, i) {
  const P = run.P; const s = P.s[i]; const kind = stepKind(s); const obj = run.obj; const w = obj.well || null;
  const scope = obj.kind === 'summary' ? (obj.short.match(/НГДУ-\d|ДЗО/) || ['НГДУ-1'])[0] : obj.kind === 'ngdu' ? obj.short : 'НГДУ-1';
  const ctx = { run, s, i, c: s.c, kind, obj, w, scope };
  const special = S[P.p] ? S[P.p](ctx) : null;
  const g = generic(ctx); const spec = special ? { facts: g.facts, ...special, special: true } : g;
  // Решение из BPMN, если форма его не задала
  // (шаблонные «Согласовать / с замечаниями» без подписей ветвей заменяются вариантами развилки, иначе движок пошёл бы по первой ветви)
  const bd = decisionOf(P, i);
  if (bd && !(spec.decision && spec.decision.options.some((o) => o.dec))) spec.decision = { q: bd.q, options: bd.options.map((o) => ({ label: cap(o), dec: o, comment: /^(нет|да)$/i.test(o) && /замечан/i.test(bd.q) ? norm(o) === 'да' : false })) };
  if (!spec.action && !spec.decision) spec.action = { label: 'Выполнить шаг', text: 'Шаг выполнен' };
  spec.sys = s.s.find((x) => /^ABAI|^КХД/.test(x)) || s.s[0] || '';
  // Подсказка — аннотации BPMN: в обычном режиме без кодов процессов и шагов и без служебных пометок («Оптимизируется:», «TO BE:» …)
  spec.hintRaw = s.n && s.n.length ? s.n.join('. ') : '';
  spec.hint = (s.n || []).map(cleanNote).filter(Boolean).join('. ');
  return spec;
}

// Результат пройденного шага для журнала: текст действия формы или выбранный вариант решения
export function stepResult(run, i) {
  const spec = formFor(run, i); const ESP = / · подписать ЭЦП$/;
  if (spec.action && spec.action.text) return spec.action.text;
  if (spec.decision) {
    const o = spec.decision.options.find((x) => !x.comment) || spec.decision.options[0]; if (!o) return null;
    const l = o.label.replace(ESP, '');
    if (/^Согласовать/.test(l)) return 'Согласовано' + (o.sign || /ЭЦП/.test(l) ? ', подписано ЭЦП' : '');
    if (/^Утвердить/.test(l)) return 'Утверждено' + (o.sign || /ЭЦП/.test(l) ? ', подписано ЭЦП' : '');
    return l.replace(/ и подписать ЭЦП$/, ', подписано ЭЦП');
  }
  return null;
}
RESULT.fn = stepResult;

